{
  "passageId": "schoenberg-twelve-tone",
  "items": [
    {
      "id": "R1",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 음악이 특정 조성에 얽매이는지라는 같은 기준에서 서로 다른 특성을 보인다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "다장조의 으뜸음과 음 배열이 조성 음악의 위계질서를 구체적인 사례로 보여 준다."
    },
    {
      "id": "R3",
      "type": "CONDITION",
      "otherName": "",
      "reason": "정해진 음계 규칙에서 벗어난 음의 포함 여부가 불협화음으로 취급되는 조건이다."
    },
    {
      "id": "R4",
      "type": "PROCESS",
      "otherName": "",
      "reason": "으뜸화음으로 시작한 다음 버금딸림화음과 딸림화음을 거치는 진행 순서를 나타낸다."
    },
    {
      "id": "R5",
      "type": "PROCESS",
      "otherName": "",
      "reason": "버금딸림화음과 딸림화음을 거친 다음 으뜸화음으로 복귀하는 진행 순서를 나타낸다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "다장조의 구체적인 화음 진행이 조성 음악의 선율 흐름이 미리 정해져 있다는 일반적 설명을 예시한다."
    },
    {
      "id": "R7",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "으뜸음 중심의 위계질서가 존재하는 조성 음악과 그것이 해체된 쇤베르크의 음악을 비교한다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "조성 음계와 12음 음렬이 장ㆍ단조의 경계를 분명하게 하는지라는 기준에서 대비된다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "반음 간격의 조밀한 음 배열이 조성의 경계를 모호하게 만드는 실제 작용을 설명한다."
    },
    {
      "id": "R10",
      "type": "CAUSE",
      "otherName": "",
      "reason": "조성 경계의 모호함이 장조와 단조가 공존하는 듯한 인상을 일으킨다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "장조와 단조가 공존하는 듯한 인상이 음악을 무질서하게 받아들이는 인식을 낳는다."
    },
    {
      "id": "R12",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "같은 음악이 무질서하게 받아들여졌지만 실제 의도는 새로운 질서를 마련하는 것이었다는 어긋남을 제시한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "음들의 내재적 관계에 기초한 형식이라는 설명을 유기적 통일성과 응집력의 원리로 상세화한다."
    },
    {
      "id": "R14",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "곡을 유기체로 완성하는 조건으로 제시된 응집력의 뜻을 음들 사이의 내적 결속으로 풀이한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유사성의 반복으로 응집력이 실현된다는 원리에서 반복될수록 응집력이 강화된다는 설명을 도출한다."
    },
    {
      "id": "R16",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "유사성의 반복으로 형성되는 응집력을 보편적 음악 질서를 이루기 위한 기반으로 삼는다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "음악적 경험을 일상적 경험이 의식의 지향성을 통해 구성된다는 설명의 사례로 제시한다."
    },
    {
      "id": "R18",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "판단 중지의 의미를 자연적 태도에서 현상학적 태도로 전환하는 것으로 풀어 설명한다."
    },
    {
      "id": "R19",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "경험이 지향성을 통해 구성된다는 후설의 원리를 조성 음악의 화음을 해석하는 데 가져다 쓴다."
    },
    {
      "id": "R20",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "판단 중지와 현상학적 환원의 원리를 쇤베르크의 조성 질서 극복에 적용한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "판단 중지를 통해 보편적 질서를 확립했다는 설명이 음악의 본질에 다가섰다는 평가를 뒷받침한다."
    },
    {
      "id": "R22",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "레보비츠가 쇤베르크의 보편적 질서 추구를 현상학의 판단 중지라는 틀로 해석한다."
    },
    {
      "id": "R23",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "필자가 범조성과 현상학적 환원의 괴리를 들어 레보비츠의 긍정적 평가를 반박한다."
    },
    {
      "id": "R24",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "모든 전제에 대한 판단을 중지하려는 현상학과 새로운 규범을 세운 쇤베르크의 입장을 비교한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "새로운 규범을 제시했다는 사실이 범조성이 모든 전제의 판단을 중지하는 현상학적 환원과 괴리된다는 판단의 근거이다."
    },
    {
      "id": "R26",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "필자가 모든 음의 동등성이라는 쇤베르크의 원리를 새로운 규범의 설정이라는 틀로 재해석한다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "평균율이 음향적 가능성의 극히 일부만 표준화했다는 사실이 이를 물리적 제약으로 보는 설명을 뒷받침한다."
    },
    {
      "id": "R28",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "아도르노의 말을 근거로 음악의 재료에도 문화적 맥락이 응축되어 있다고 설명한다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "전통적 음악의 토대인 평균율을 그대로 수용했다는 사실에서 전통적 재료를 고수했다는 비유적 평가를 도출한다."
    },
    {
      "id": "R30",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "음악 재료 자체에 문화적 맥락이 응축되어 있다는 원리를 쇤베르크의 평균율 수용을 평가하는 데 적용한다."
    },
    {
      "id": "R31",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "미시적 직관을 강조한 후설과 거시적 구조에 치중한 쇤베르크의 관점을 비교한다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "거시적 구조로만 음악을 조망한 것이 개별 음의 미시적 체험을 간과하는 결과로 이어진다."
    },
    {
      "id": "R33",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "환원 이후에는 현상 그 자체가 남아야 한다는 기준을 쇤베르크의 음악에 적용하여 순수 현상에 이르지 못했다고 판단한다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "순수 현상에 이르지 못했다는 점이 쇤베르크의 음악관이 현상학적 잔여 개념과 어긋난다는 판단을 뒷받침한다."
    },
    {
      "id": "R35",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "규범과 음악 재료의 전제에 관한 비판에서 미시적 체험과 현상학적 잔여의 문제로 논의를 넓힌다."
    },
    {
      "id": "R36",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "필자가 새로운 규범과 평균율의 유지 및 거시적 구조 편중을 들어 레보비츠의 현상학적 평가를 반박한다."
    }
  ]
}

